resources.string:
"#version 300 es\n"

uniform mat4 uMVPMatrix;
uniform float wave;
uniform vec3 position[20];
in vec4 vPosition;
in vec3 vNormal;
in vec2 a_TexCoordinate;
out vec2 texCoord;


void main() {


    vec4 outPos = vPosition;
    vec4 nvpPos = uMVPMatrix * vec4(vPosition.xyz, 1.0);

    outPos.x = outPos.x + sin(wave + outPos.z*100.0 + nvpPos.x*0.5)*0.25*outPos.y;



    gl_Position = uMVPMatrix * vec4(outPos.xyz, 1.0);

    texCoord = a_TexCoordinate;
}

precision mediump float;
uniform sampler2D u_Texture;

varying vec2 texCoord;

void main() {

vec4 color = texture2D(u_Texture, texCoord);


if(color.a<0.5){
    discard;
}

gl_FragColor = color;
}
